"""Market structure and liquidity evaluator for Model B.

Detects swing highs/lows, liquidity sweep-reclaim dynamics, order book imbalance confirmations,
and Cumulative Volume Delta (CVD) alignment on 1H bar closes.
"""

from typing import Any, Dict, List, Optional, Tuple
from dataclasses import dataclass

from src.core.types import Candle, Direction
from src.exchange.normalized import LiquiditySnapshot


@dataclass
class ModelBSetupSignal:
    """Raw signal generated by Model B liquidity evaluation."""
    symbol: str
    direction: Direction
    entry_price: float
    stop_loss: float
    take_profit_1: float
    take_profit_2: float
    signal_type: str  # "SWEEP_RECLAIM" or "ABSORPTION_BREAKOUT"
    confidence_score: float
    liquidity_snapshot: LiquiditySnapshot
    reasons: List[str]
    timestamp_ms: int


def find_recent_swings(
    candles: List[Candle],
    left_bars: int = 3,
    right_bars: int = 2,
) -> Tuple[List[Tuple[int, float]], List[Tuple[int, float]]]:
    """Identify confirmed swing highs and swing lows.
    
    Returns:
        (swing_highs, swing_lows) where each element is (candle_index, price).
    """
    n = len(candles)
    swing_highs: List[Tuple[int, float]] = []
    swing_lows: List[Tuple[int, float]] = []

    if n < left_bars + right_bars + 1:
        return swing_highs, swing_lows

    for i in range(left_bars, n - right_bars):
        c = candles[i]
        # Check swing high
        is_high = True
        for j in range(i - left_bars, i + right_bars + 1):
            if j != i and candles[j].high >= c.high:
                is_high = False
                break
        if is_high:
            swing_highs.append((i, c.high))

        # Check swing low
        is_low = True
        for j in range(i - left_bars, i + right_bars + 1):
            if j != i and candles[j].low <= c.low:
                is_low = False
                break
        if is_low:
            swing_lows.append((i, c.low))

    return swing_highs, swing_lows


def evaluate_liquidity_setup(
    symbol: str,
    candles: List[Candle],
    snapshot: LiquiditySnapshot,
    min_imbalance: float = 0.05,
    min_absorption: float = 0.25,
    max_spread_bps: float = 15.0,
    buffer_pct: float = 0.001,
    timeframe_label: str = "1H",
) -> Optional[ModelBSetupSignal]:
    """Evaluate candle series and liquidity snapshot for Model B setup."""
    if len(candles) < 20:
        return None

    tf_lbl = str(timeframe_label or "1H").upper()

    # Spread gate: Reject wide-spread illiquid pairs
    if snapshot.spread_bps > max_spread_bps:
        return None

    last_closed = candles[-1]
    swing_highs, swing_lows = find_recent_swings(candles[:-1], left_bars=3, right_bars=2)

    # 1. Evaluate LONG Liquidity Sweep-Reclaim
    if swing_lows:
        # Most recent key swing low
        _, key_low = swing_lows[-1]

        # Conditions for Long Sweep-Reclaim:
        # A) Last closed bar or second-last bar pierced below key_low
        # B) Last closed bar closed strictly above key_low
        swept = (last_closed.low < key_low) or (len(candles) >= 2 and candles[-2].low < key_low)
        reclaimed = swept and (last_closed.close > key_low)
        confirmed_close = last_closed.close > last_closed.open

        # C) Liquidity confirmation: bid depth imbalance or positive CVD or absorption
        has_bid_imbalance = snapshot.imbalance_25bps >= min_imbalance
        has_positive_cvd = snapshot.cvd_1h > 0
        has_absorption = snapshot.absorption_score >= min_absorption

        liquidity_confirmed = has_bid_imbalance or (has_positive_cvd and has_absorption)

        if reclaimed and liquidity_confirmed and confirmed_close:
            entry_px = last_closed.close
            sweep_low = min(last_closed.low, candles[-2].low if len(candles) >= 2 else last_closed.low)
            sl_px = sweep_low * (1.0 - buffer_pct)
            risk_dist = entry_px - sl_px

            if risk_dist > 0:
                tp1 = entry_px + (risk_dist * 1.5)
                # Next target: nearest swing high above entry or 3R
                high_targets = [px for _, px in swing_highs if px > tp1]
                tp2 = high_targets[0] if high_targets else entry_px + (risk_dist * 3.0)

                reasons = [
                    f"{tf_lbl} Long Liquidity Sweep-Reclaim of swing low {key_low:.4f}",
                    f"Closed at {last_closed.close:.4f} with depth imbalance {snapshot.imbalance_25bps:+.2%}",
                    f"CVD=${snapshot.cvd_1h:,.0f}, absorption={snapshot.absorption_score:.2f}",
                ]
                conf = 0.70 + (0.15 if has_bid_imbalance else 0.0) + (0.15 if has_absorption else 0.0)

                return ModelBSetupSignal(
                    symbol=symbol,
                    direction=Direction.LONG,
                    entry_price=entry_px,
                    stop_loss=sl_px,
                    take_profit_1=tp1,
                    take_profit_2=tp2,
                    signal_type="SWEEP_RECLAIM",
                    confidence_score=min(0.95, conf),
                    liquidity_snapshot=snapshot,
                    reasons=reasons,
                    timestamp_ms=last_closed.timestamp_ms,
                )

    # 2. Evaluate SHORT Liquidity Sweep-Reclaim
    if swing_highs:
        _, key_high = swing_highs[-1]

        swept = (last_closed.high > key_high) or (len(candles) >= 2 and candles[-2].high > key_high)
        reclaimed = swept and (last_closed.close < key_high)
        confirmed_close = last_closed.close < last_closed.open

        has_ask_imbalance = snapshot.imbalance_25bps <= -min_imbalance
        has_negative_cvd = snapshot.cvd_1h < 0
        has_absorption = snapshot.absorption_score >= min_absorption

        liquidity_confirmed = has_ask_imbalance or (has_negative_cvd and has_absorption)

        if reclaimed and liquidity_confirmed and confirmed_close:
            entry_px = last_closed.close
            sweep_high = max(last_closed.high, candles[-2].high if len(candles) >= 2 else last_closed.high)
            sl_px = sweep_high * (1.0 + buffer_pct)
            risk_dist = sl_px - entry_px

            if risk_dist > 0:
                tp1 = entry_px - (risk_dist * 1.5)
                low_targets = [px for _, px in swing_lows if px < tp1]
                tp2 = low_targets[0] if low_targets else entry_px - (risk_dist * 3.0)

                reasons = [
                    f"{tf_lbl} Short Liquidity Sweep-Reclaim of swing high {key_high:.4f}",
                    f"Closed at {last_closed.close:.4f} with depth imbalance {snapshot.imbalance_25bps:+.2%}",
                    f"CVD=${snapshot.cvd_1h:,.0f}, absorption={snapshot.absorption_score:.2f}",
                ]
                conf = 0.70 + (0.15 if has_ask_imbalance else 0.0) + (0.15 if has_absorption else 0.0)

                return ModelBSetupSignal(
                    symbol=symbol,
                    direction=Direction.SHORT,
                    entry_price=entry_px,
                    stop_loss=sl_px,
                    take_profit_1=tp1,
                    take_profit_2=tp2,
                    signal_type="SWEEP_RECLAIM",
                    confidence_score=min(0.95, conf),
                    liquidity_snapshot=snapshot,
                    reasons=reasons,
                    timestamp_ms=last_closed.timestamp_ms,
                )

    return None
